-- Cloudflare migration support for existing BDZTEAM Supabase project.
create table if not exists public.key_tokens (id bigint generated by default as identity primary key, token_hash text not null unique, product_id bigint not null references public.products(id) on delete cascade, client_hash text not null, expires_at timestamptz not null, used_at timestamptz null, created_at timestamptz not null default now());
create index if not exists idx_key_tokens_expiry on public.key_tokens(expires_at);
create index if not exists idx_key_tokens_client on public.key_tokens(client_hash);
create table if not exists public.shortener_usage (id bigint generated by default as identity primary key, slot_position integer not null, client_hash text not null, usage_date date not null default current_date, count integer not null default 0, unique(slot_position, client_hash, usage_date));
alter table public.key_tokens enable row level security;
alter table public.shortener_usage enable row level security;
create or replace function public.create_key_token(p_token_hash text,p_product_id bigint,p_client_hash text,p_ttl_seconds integer default 900) returns timestamptz language plpgsql security definer set search_path=public as $$ declare v_expires timestamptz; begin if p_ttl_seconds<60 or p_ttl_seconds>1800 then raise exception 'invalid ttl'; end if; v_expires:=now()+make_interval(secs=>p_ttl_seconds); insert into public.key_tokens(token_hash,product_id,client_hash,expires_at) values(p_token_hash,p_product_id,p_client_hash,v_expires); return v_expires; end; $$;
revoke all on function public.create_key_token(text,bigint,text,integer) from public,anon,authenticated; grant execute on function public.create_key_token(text,bigint,text,integer) to service_role;
create or replace function public.verify_key_token(p_token_hash text,p_client_hash text,p_consume boolean default false) returns bigint language plpgsql security definer set search_path=public as $$ declare v_product_id bigint; v_used_at timestamptz; v_expires timestamptz; v_client text; begin select product_id,used_at,expires_at,client_hash into v_product_id,v_used_at,v_expires,v_client from public.key_tokens where token_hash=p_token_hash limit 1; if not found or v_client<>p_client_hash or v_expires<=now() or v_used_at is not null then return null; end if; if p_consume then update public.key_tokens set used_at=now() where token_hash=p_token_hash and used_at is null and expires_at>now() and client_hash=p_client_hash; if not found then return null; end if; end if; return v_product_id; end; $$;
revoke all on function public.verify_key_token(text,text,boolean) from public,anon,authenticated; grant execute on function public.verify_key_token(text,text,boolean) to service_role;
create or replace function public.reserve_shortener_slot(p_slot_position integer,p_client_hash text,p_limit integer) returns boolean language plpgsql security definer set search_path=public as $$ declare v_count integer; begin if p_limit<1 then return false; end if; insert into public.shortener_usage(slot_position,client_hash,usage_date,count) values(p_slot_position,p_client_hash,current_date,1) on conflict(slot_position,client_hash,usage_date) do update set count=public.shortener_usage.count+1 where public.shortener_usage.count<p_limit returning count into v_count; return found; end; $$;
revoke all on function public.reserve_shortener_slot(integer,text,integer) from public,anon,authenticated; grant execute on function public.reserve_shortener_slot(integer,text,integer) to service_role;
create or replace function public.release_shortener_slot(p_slot_position integer,p_client_hash text) returns void language plpgsql security definer set search_path=public as $$ begin update public.shortener_usage set count=greatest(0,count-1) where slot_position=p_slot_position and client_hash=p_client_hash and usage_date=current_date; end; $$;
revoke all on function public.release_shortener_slot(integer,text) from public,anon,authenticated; grant execute on function public.release_shortener_slot(integer,text) to service_role;
create or replace function public.claim_or_create_key(p_product_id bigint,p_duration_hours integer default 10,p_claimed_ip text default null) returns table(key_code text,product_id bigint,duration_hours integer,expires_at timestamptz) language plpgsql security definer set search_path=public as $$ declare k public.keys%rowtype; v_code text; v_duration integer:=greatest(1,least(168,coalesce(p_duration_hours,10))); begin select * into k from public.keys where product_id=p_product_id and status='ACTIVE' and expires_at is not null and expires_at>now() and claimed_at is null order by id for update skip locked limit 1; if found then update public.keys set claimed_at=now(),claimed_ip=p_claimed_ip where id=k.id; return query select k.key_code,k.product_id,k.duration_hours,k.expires_at; return; end if; v_code:='BDZ-'||upper(substr(md5(random()::text||clock_timestamp()::text),1,12)); insert into public.keys(key_code,product_id,duration_hours,status,expires_at,claimed_at,claimed_ip) values(v_code,p_product_id,v_duration,'ACTIVE',now()+make_interval(hours=>v_duration),now(),p_claimed_ip) returning * into k; return query select k.key_code,k.product_id,k.duration_hours,k.expires_at; end; $$;
revoke all on function public.claim_or_create_key(bigint,integer,text) from public,anon,authenticated; grant execute on function public.claim_or_create_key(bigint,integer,text) to service_role;
